<?php
namespace App\Services; use Illuminate\Http\Client\ConnectionException; use Illuminate\Http\Client\RequestException; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Log; use RuntimeException;
final class DependencyClient {
 public function deliver(array $payload,string $correlationId):string{$attempt=0;$started=microtime(true);try{$response=Http::acceptJson()->withHeaders(['X-Correlation-ID'=>$correlationId])->connectTimeout(config('services.dependency.connect_timeout'))->timeout(config('services.dependency.timeout'))->retry(2,function(int $attempt){return $attempt*100;},function($exception,$request)use(&$attempt){$attempt++;$status=$exception instanceof RequestException?$exception->response->status():null;$retry=$exception instanceof ConnectionException||$status===429||($status!==null&&$status>=500);Log::warning('dependency.retry',['dependency'=>'notification-simulator','correlation_id'=>$request->header('X-Correlation-ID')[0]??null,'attempt'=>$attempt,'status'=>$status,'retryable'=>$retry]);return $retry;})->post(config('services.dependency.url').'/deliveries',$payload);$response->throw();$body=$response->json();if(!is_array($body)||($body['accepted']??null)!==true||!is_string($body['deliveryId']??null))throw new RuntimeException('Malformed dependency response');Log::info('dependency.complete',['dependency'=>'notification-simulator','correlation_id'=>$correlationId,'status'=>$response->status(),'duration_ms'=>round((microtime(true)-$started)*1000,2)]);return $body['deliveryId'];}catch(\Throwable $e){Log::error('dependency.failed',['dependency'=>'notification-simulator','correlation_id'=>$correlationId,'error_category'=>$e instanceof ConnectionException?'unavailable':'invalid_or_http','exception'=>get_class($e)]);throw $e;}}
}
